use rand::seq::IndexedRandom;

/// Built-in lists, generated by `scripts/wordlists.py` (see `words/README.md`).
const BUILT_IN: &[(&str, &str)] = &[
    ("english", include_str!("../words/english.txt")),
    ("english_1k", include_str!("../words/english_1k.txt")),
    ("english_10k", include_str!("../words/english_10k.txt")),
    ("french", include_str!("../words/french.txt")),
    ("french_1k", include_str!("../words/french_1k.txt")),
    ("french_10k", include_str!("../words/french_10k.txt")),
];

/// Loads a word list: `<config>/words/<lang>.txt` if it exists, else a built-in list.
pub fn load(lang: &str) -> Result<Vec<String>, String> {
    let user = crate::dirs().map(|d| d.config_dir().join("words").join(format!("{lang}.txt")));
    let text = match user.and_then(|p| std::fs::read_to_string(p).ok()) {
        Some(t) => t,
        None => match BUILT_IN.iter().find(|(name, _)| *name == lang) {
            Some((_, text)) => text.to_string(),
            None => {
                let names: Vec<&str> = BUILT_IN.iter().map(|(name, _)| *name).collect();
                return Err(format!(
                    "unknown language '{lang}' (built-in: {})",
                    names.join(", ")
                ));
            }
        },
    };
    let words: Vec<String> = text.split_whitespace().map(str::to_string).collect();
    if words.is_empty() {
        return Err(format!("word list '{lang}' is empty"));
    }
    Ok(words)
}

pub fn pick(list: &[String], n: usize) -> Vec<String> {
    let mut rng = rand::rng();
    let mut out: Vec<String> = Vec::with_capacity(n);
    while out.len() < n {
        let w = list.choose(&mut rng).unwrap();
        // Avoid the same word twice in a row when the list allows it.
        if list.len() == 1 || out.last() != Some(w) {
            out.push(w.clone());
        }
    }
    out
}

/// Built-in languages, then user word lists from `<config>/words/`.
pub fn available() -> Vec<String> {
    let mut langs: Vec<String> = BUILT_IN.iter().map(|(name, _)| name.to_string()).collect();
    let dir = crate::dirs().map(|d| d.config_dir().join("words"));
    if let Some(entries) = dir.and_then(|d| std::fs::read_dir(d).ok()) {
        let mut user: Vec<String> = entries
            .filter_map(|e| {
                let p = e.ok()?.path();
                (p.extension()? == "txt").then(|| p.file_stem()?.to_str().map(str::to_string))?
            })
            .filter(|l| !langs.contains(l))
            .collect();
        user.sort();
        langs.extend(user);
    }
    langs
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn built_in_lists_are_clean() {
        for (name, text) in BUILT_IN {
            let words: Vec<&str> = text.lines().collect();
            assert!(!words.is_empty(), "{name} is empty");
            assert!(
                words
                    .iter()
                    .all(|w| !w.is_empty() && !w.contains(char::is_whitespace)),
                "{name}"
            );
            assert_eq!(
                words.iter().collect::<HashSet<_>>().len(),
                words.len(),
                "{name} has duplicates"
            );
        }
    }
}
